// =============================================================================
// Module: snax_llm_sequencer_area_opt.sv
// Description: Area-optimized Unified Hardware Orchestration Sequencer.
//              Functionally identical to snax_llm_sequencer.sv, but all
//              multi-dimensional addresses are generated by incremental
//              pointers. Static job parameters are computed once through a
//              single shared 16x16 multiplier; runtime chunk products use a
//              tiny 5-bit shift-add. Dynamic 32x32 multiplier trees are gone.
//
// Supported Workloads:
//   - cfg_dma_wb_i == 1          : Standalone Gearbox DMA (TCDM <-> DRAM)
//   - cfg_op_mode_i == 2'b00     : 4-Loop Output-Stationary GEMM
//                                  (M_macro -> N_16 -> M_sub -> K_TILES)
//                                  with Ping-Pong A/O Macro-DMA, W Ring Reuse,
//                                  Port-B Rolling Drain, and Fused V-Transpose
//   - cfg_op_mode_i == 2'b01     : FlashAttention + GQA + Online Softmax
//                                  (h_kv -> h_grp -> Q_macro -> qi -> dvi -> kj)
//                                  with KV-Pinning, Ring Prefetch, Macro-DMA
//                                  Q/O Ping-Pong, and Dynamic Causal Masking
//   - cfg_op_mode_i == 2'b10     : Hardware Decode / TCDM V-Transpose + LogQ
//                                  (u_read_fp16 2D -> u_transpose_buffer ->
//                                   u_log_quantizer -> u_write_out MODE_V)
//   - cfg_op_mode_i == 2'b11     : TCDM FP16 Readback + Requantize
//
// Decoupled 3-Sub-FSM Architecture:
//   - Sub-FSM 1 (cmp_state_q): Compute, Streamer, V/RD & Loop Coordinator
//   - Sub-FSM 2 (dr_state_q) : Port-B Drain & OUT_PIPE_CREDITS Guard + WAR Guard
//   - Sub-FSM 3 (dma_state_q): DMA Arbiter & Ring/Ping-Pong/KV-Pin Controller
// =============================================================================

`timescale 1ns/1ps

module snax_llm_sequencer #(
    parameter int unsigned ADDR_WIDTH       = 32,
    parameter int unsigned NUM_LANES        = 16,
    parameter int unsigned NUM_RING_SLOTS   = 4,
    parameter int unsigned SLOT_SIZE_BYTES  = 128 * 1024,
    parameter int unsigned OUT_PIPE_CREDITS = 4,
    parameter int unsigned CAP_O_TILES      = 16
)(
    input  logic                                clk,
    input  logic                                rst_n,

    // =========================================================================
    // 1. JOB CONTROL & CONFIGURATION DESCRIPTOR
    // =========================================================================
    input  logic                                start_i,
    output logic                                busy_o,
    output logic                                done_o,

    input  logic [1:0]                          cfg_op_mode_i,
    input  logic                                cfg_is_causal_i,
    input  logic                                cfg_enable_dma_i,
    input  logic                                cfg_dma_wb_i,
    input  logic                                cfg_gemm_decode_i,
    input  logic [1:0]                          cfg_out_mode_i,
    input  logic [7:0]                          cfg_gemm_k_tiles_m1_i,
    input  logic [7:0]                          cfg_gqa_group_m1_i,
    input  logic                                cfg_act_bank_layout_i,
    input  logic                                cfg_out_bank_layout_i,

    // Attention dimensions
    input  logic [7:0]                          cfg_attn_h_i,
    input  logic [15:0]                         cfg_attn_q_tiles_i,
    input  logic [3:0]                          cfg_attn_m_q_i,
    input  logic [15:0]                         cfg_attn_dv_tiles_i,
    input  logic [15:0]                         cfg_attn_kv_tiles_i,
    input  logic [15:0]                         cfg_attn_k_blocks_i,

    // GEMM dimensions
    input  logic [15:0]                         cfg_gemm_n_tiles_i,
    input  logic [15:0]                         cfg_gemm_m_tiles_i,
    input  logic [15:0]                         cfg_gemm_k_blocks_i,

    // Base addresses & strides
    input  logic [ADDR_WIDTH-1:0]               cfg_tcdm_ring_base_i,
    input  logic [ADDR_WIDTH-1:0]               cfg_tcdm_q_base_i,
    input  logic [ADDR_WIDTH-1:0]               cfg_tcdm_out_base_i,
    input  logic [ADDR_WIDTH-1:0]               cfg_dram_kv_base_i,
    input  logic [31:0]                         cfg_stride_tile_i,

    // V-Transpose / Readback descriptors
    input  logic [ADDR_WIDTH-1:0]               cfg_v_base_i,
    input  logic [31:0]                         cfg_v_num_batches_i,
    input  logic [ADDR_WIDTH-1:0]               cfg_v_out_base_i,
    input  logic [ADDR_WIDTH-1:0]               cfg_rd_base_i,
    input  logic [31:0]                         cfg_rd_num_vectors_i,
    input  logic [31:0]                         cfg_rd_line_stride_i,
    input  logic [ADDR_WIDTH-1:0]               cfg_rd_out_base_i,

    // Macro-Tiling & Attention Extended DMA controls
    input  logic                                cfg_gemm_macro_dma_i     `ifndef SYNTHESIS = 1'b0 `endif,
    input  logic [7:0]                          cfg_gemm_m_sub_tiles_i   `ifndef SYNTHESIS = 8'd0 `endif,
    input  logic [7:0]                          cfg_gemm_n_sub_tiles_i   `ifndef SYNTHESIS = 8'd0 `endif,
    input  logic [ADDR_WIDTH-1:0]               cfg_dram_act_base_i      `ifndef SYNTHESIS = '0 `endif,
    input  logic [ADDR_WIDTH-1:0]               cfg_dram_out_base_i      `ifndef SYNTHESIS = '0 `endif,
    input  logic [31:0]                         cfg_macro_a_buf_stride_i `ifndef SYNTHESIS = 32'd0 `endif,
    input  logic [31:0]                         cfg_macro_o_buf_stride_i `ifndef SYNTHESIS = 32'd0 `endif,
    input  logic                                cfg_attn_kv_pin_i        `ifndef SYNTHESIS = 1'b0 `endif,
    input  logic                                cfg_attn_sep_kv_i        `ifndef SYNTHESIS = 1'b0 `endif,
    input  logic [ADDR_WIDTH-1:0]               cfg_dram_v_base_i        `ifndef SYNTHESIS = '0 `endif,
    input  logic [13:0]                         cfg_attn_kv_past_tiles_i `ifndef SYNTHESIS = 14'd0 `endif,

    // =========================================================================
    // 2. DMA MASTER INTERFACE
    // =========================================================================
    output logic                                dma_req_valid_o,
    input  logic                                dma_req_ready_i,
    output logic [1:0]                          dma_req_dir_o,
    output logic [ADDR_WIDTH-1:0]               dma_req_dram_addr_o,
    output logic [ADDR_WIDTH-1:0]               dma_req_tcdm_addr_o,
    output logic [31:0]                         dma_req_size_bytes_o,
    input  logic                                dma_done_i,

    // =========================================================================
    // 3. ACTIVATION STREAMER INTERFACE
    // =========================================================================
    output logic                                act_start_o,
    output logic [ADDR_WIDTH-1:0]               act_base_o,
    output logic [31:0]                         act_k_blocks_o,
    output logic [31:0]                         act_k_stride_o,
    output logic [31:0]                         act_tokens_o,
    output logic [31:0]                         act_token_stride_o,
    input  logic                                act_busy_i,
    input  logic                                act_valid_i,
    output logic                                act_ready_o,

    // =========================================================================
    // 4. 16-CHANNEL WEIGHT / KV STREAMER INTERFACE
    // =========================================================================
    output logic                                wt_start_o,
    output logic [ADDR_WIDTH-1:0]               wt_base_o,
    output logic [31:0]                         wt_repeat_o,
    output logic [31:0]                         wt_k_blocks_o,
    output logic [31:0]                         wt_k_stride_o,
    output logic [31:0]                         wt_num_tiles_o,
    output logic [31:0]                         wt_tile_step_o,
    input  logic                                wt_busy_i,
    input  logic [NUM_LANES-1:0]                wt_valid_i,
    output logic [NUM_LANES-1:0]                wt_ready_o,

    // =========================================================================
    // 5. WRITE-OUT STREAMER INTERFACE
    // =========================================================================
    output logic                                wo_start_o,
    output logic [1:0]                          wo_mode_o,
    output logic [ADDR_WIDTH-1:0]               wo_base_o,
    output logic [31:0]                         wo_num_vectors_o,
    output logic [31:0]                         wo_line_stride_o,
    output logic [31:0]                         wo_num_batches_o,
    output logic [31:0]                         wo_batch_stride_o,
    output logic [31:0]                         wo_dim2_cnt_o,
    output logic [31:0]                         wo_dim2_stride_o,
    output logic [31:0]                         wo_dim3_cnt_o,
    output logic [31:0]                         wo_dim3_stride_o,
    input  logic                                wo_busy_i,
    input  logic                                wo_done_i,

    // =========================================================================
    // 6. V-TRANSPOSE & TCDM FP16 READBACK STREAMER INTERFACES
    // =========================================================================
    output logic                                v_start_o,
    output logic [31:0]                         v_num_batches_o,
    input  logic                                v_busy_i,
    input  logic                                v_done_i,
    output logic                                rd_start_o,
    output logic [ADDR_WIDTH-1:0]               rd_base_o,
    output logic [31:0]                         rd_num_vectors_o,
    output logic [31:0]                         rd_line_stride_o,
    output logic [31:0]                         rd_vec_stride_o,
    output logic [31:0]                         rd_num_batches_o,
    output logic [31:0]                         rd_batch_stride_o,
    input  logic                                rd_busy_i,
    input  logic                                rd_done_i,

    // =========================================================================
    // 7. COMPUTE CORE CONTROL INTERFACE
    // =========================================================================
    output logic [1:0]                          cfg_mode_o,
    output logic                                cfg_row_start_o,
    output logic [NUM_LANES-1:0]                cfg_key_mask_o,
    output logic                                cfg_enable_slq_o,
    output logic                                tile_drain_req_o,
    output logic [3:0]                          tile_drain_idx_o,
    output logic                                tile_clear_on_drain_o,
    output logic [NUM_LANES-1:0]                lane_valid_o,
    output logic [3:0]                          lane_acc_idx_o,
    input  logic                                p_fifo_empty_i,
    input  logic                                p_fifo_almost_full_i,
    input  logic                                core_fp16_valid_i,
    input  logic                                core_out_fifo_ready_i,
    input  logic                                core_fp16_ready_i `ifndef SYNTHESIS = 1'b0 `endif
);

    // =========================================================================
    // SECTION 0: PARAMETERS, STATE TYPES & SHARED GEOMETRY
    // =========================================================================
    // SECTION 0: SHARED GEOMETRY & INTER-FSM WIRING
    // =========================================================================
    localparam int unsigned PTR_W = (NUM_RING_SLOTS > 1) ? $clog2(NUM_RING_SLOTS) : 1;
    localparam int unsigned CNT_W = $clog2(NUM_RING_SLOTS + 1);

    localparam logic [4:0] CMP_IDLE = 5'd0;
    localparam logic [4:0] CMP_DONE = 5'd18;

    wire is_dma_wb = cfg_dma_wb_i;
    wire is_gemm   = !cfg_dma_wb_i && (cfg_op_mode_i == 2'b00);
    wire is_attn   = !cfg_dma_wb_i && (cfg_op_mode_i == 2'b01);
    wire is_vtrans = !cfg_dma_wb_i && (cfg_op_mode_i == 2'b10);
    wire is_rdback = !cfg_dma_wb_i && (cfg_op_mode_i == 2'b11);

    wire macro_dma_en        = cfg_gemm_macro_dma_i && cfg_enable_dma_i && (is_gemm || is_attn);
    wire attn_kv_pin_en      = cfg_attn_kv_pin_i && cfg_enable_dma_i && is_attn;
    wire w_ring_reuse_active = is_gemm && cfg_enable_dma_i && (cfg_gemm_k_tiles_m1_i == 8'd0);

    wire [15:0] macro_m_total = is_attn ? cfg_attn_q_tiles_i : cfg_gemm_m_tiles_i;
    wire [15:0] eff_m_sub     = (!macro_dma_en || (cfg_gemm_m_sub_tiles_i == 8'd0) ||
                                 ({8'd0, cfg_gemm_m_sub_tiles_i} >= macro_m_total))
                                ? macro_m_total : {8'd0, cfg_gemm_m_sub_tiles_i};
    wire [31:0] a_stride_eff  = (cfg_macro_a_buf_stride_i != 32'd0) ? cfg_macro_a_buf_stride_i : 32'h0002_0000;
    wire [31:0] o_stride_eff  = (cfg_macro_o_buf_stride_i != 32'd0) ? cfg_macro_o_buf_stride_i : 32'h0002_0000;
    wire [31:0] o_cmp_base_0  = (is_gemm && (cfg_out_mode_i == 2'd3)) ? cfg_v_out_base_i : cfg_tcdm_out_base_i;
    wire        o_dma_is_16bank = is_gemm &&
                                  ((cfg_out_mode_i == 2'd2) || (cfg_out_mode_i == 2'd3) ||
                                   ((cfg_out_mode_i == 2'd0) && cfg_out_bank_layout_i && !cfg_gemm_decode_i));

    // Inter-FSM wires & TB-observable aliases
    logic [4:0]  cmp_state_q;
    logic [1:0]  dr_state_q;
    logic        dma_state_q;
    logic [4:0]  dr_slot_q;
    logic [3:0]  inflight_out_cnt_q;
    logic        dr_busy, gemm_beat_ok, dma_busy_q;
    logic        w_buf_ready, a_buf_ready;
    logic [1:0]  o_buf_wb_busy_q;
    logic [CNT_W-1:0] w_ready_tiles_q;
    logic [19:0] ring_rd_off_q;
    logic [7:0]  pin_active_hkv_q;
    logic [15:0] k_pinned_cnt_q;
    logic [31:0] v_pinned_cnt_q;

    logic        drain_start_pulse, sm_drain_req, sm_row_start;
    logic [3:0]  sm_drain_idx;
    logic [NUM_LANES-1:0] auto_causal_mask;

    logic        pinit_sync, a_cmp_rd_sel_q, o_cmp_sel_q, last_o_chunk, last_macro_m;
    logic        w_release_credit_pulse, macro_a_rel_pulse, o_flush_commit_pulse, kv_pin_rel_hkv_pulse;
    logic        attn_k_ready, attn_v_ready;
    logic [31:0] o_wb_bytes_q, attn_wb_bytes_q, o_wb_macro_step;
    logic [31:0] a_step_h_q, a_full_bytes_q, kt_stride_q, kt_stride_attn_q, sz_kv0_q;
    logic [10:0] k_blk_head_blk, k_preload_step_blk, packed_k_step_blk;
    logic [15:0] packed_v_off_idx_q;

    // TB-observable counters / status
    logic [15:0] cnt_gn_q, cnt_gm_q, cnt_gk_q;
    logic [7:0]  cnt_kt_q;
    logic [3:0]  cnt_gbeat_q;
    logic [7:0]  cnt_h_q;
    logic [15:0] cnt_qi_q, cnt_dvi_q, cnt_kj_q;
    logic [3:0]  cnt_m_q, cnt_dr_q;
    logic        qk_compute_fire, pv_compute_fire;

    wire [4:0] state_q     = cmp_state_q;
    wire       nrm_busy    = dr_busy;
    wire [1:0] nrm_state_q = dr_state_q;
    wire [3:0] nrm_dr_q    = dr_slot_q[3:0];

    // =========================================================================
    // SUB-FSM 1: COMPUTE, PARAMETER-INIT, ATTENTION, V-TRANS & READBACK
    // =========================================================================
    snax_seq_cmp_fsm #(
        .ADDR_WIDTH     (ADDR_WIDTH),
        .NUM_LANES      (NUM_LANES),
        .NUM_RING_SLOTS (NUM_RING_SLOTS),
        .CAP_O_TILES    (CAP_O_TILES)
    ) u_cmp_fsm (
        .clk                     (clk),
        .rst_n                   (rst_n),
        .start_i                 (start_i),
        .is_dma_wb_i             (is_dma_wb),
        .is_gemm_i               (is_gemm),
        .is_attn_i               (is_attn),
        .is_vtrans_i             (is_vtrans),
        .is_rdback_i             (is_rdback),
        .cfg_enable_dma_i        (cfg_enable_dma_i),
        .macro_dma_en_i          (macro_dma_en),
        .attn_kv_pin_en_i        (attn_kv_pin_en),
        .w_ring_reuse_active_i   (w_ring_reuse_active),
        .cfg_gemm_decode_i       (cfg_gemm_decode_i),
        .cfg_out_mode_i          (cfg_out_mode_i),
        .cfg_gemm_k_tiles_m1_i   (cfg_gemm_k_tiles_m1_i),
        .cfg_gqa_group_m1_i      (cfg_gqa_group_m1_i),
        .cfg_act_bank_layout_i   (cfg_act_bank_layout_i),
        .cfg_out_bank_layout_i   (cfg_out_bank_layout_i),
        .cfg_is_causal_i         (cfg_is_causal_i),
        .cfg_attn_h_i            (cfg_attn_h_i),
        .cfg_attn_q_tiles_i      (cfg_attn_q_tiles_i),
        .cfg_attn_m_q_i          (cfg_attn_m_q_i),
        .cfg_attn_dv_tiles_i     (cfg_attn_dv_tiles_i),
        .cfg_attn_kv_tiles_i     (cfg_attn_kv_tiles_i),
        .cfg_attn_k_blocks_i     (cfg_attn_k_blocks_i),
        .cfg_attn_sep_kv_i       (cfg_attn_sep_kv_i),
        .cfg_attn_kv_past_tiles_i(cfg_attn_kv_past_tiles_i),
        .cfg_gemm_n_tiles_i      (cfg_gemm_n_tiles_i),
        .cfg_gemm_m_tiles_i      (cfg_gemm_m_tiles_i),
        .cfg_gemm_k_blocks_i     (cfg_gemm_k_blocks_i),
        .cfg_gemm_n_sub_tiles_i  (cfg_gemm_n_sub_tiles_i),
        .cfg_tcdm_ring_base_i    (cfg_tcdm_ring_base_i),
        .cfg_tcdm_q_base_i       (cfg_tcdm_q_base_i),
        .cfg_tcdm_out_base_i     (cfg_tcdm_out_base_i),
        .cfg_dram_kv_base_i      (cfg_dram_kv_base_i),
        .cfg_stride_tile_i       (cfg_stride_tile_i),
        .cfg_v_base_i            (cfg_v_base_i),
        .cfg_v_num_batches_i     (cfg_v_num_batches_i),
        .cfg_v_out_base_i        (cfg_v_out_base_i),
        .cfg_rd_base_i           (cfg_rd_base_i),
        .cfg_rd_num_vectors_i    (cfg_rd_num_vectors_i),
        .cfg_rd_line_stride_i    (cfg_rd_line_stride_i),
        .cfg_rd_out_base_i       (cfg_rd_out_base_i),
        .macro_m_total_i         (macro_m_total),
        .eff_m_sub_i             (eff_m_sub),
        .a_stride_eff_i          (a_stride_eff),
        .o_stride_eff_i          (o_stride_eff),
        .dr_busy_i               (dr_busy),
        .gemm_beat_ok_i          (gemm_beat_ok),
        .inflight_out_cnt_i      (inflight_out_cnt_q),
        .dma_state_i             (dma_state_q),
        .dma_busy_i              (dma_busy_q),
        .dma_req_ready_i         (dma_req_ready_i),
        .dma_done_i              (dma_done_i),
        .w_buf_ready_i           (w_buf_ready),
        .a_buf_ready_i           (a_buf_ready),
        .o_buf_wb_busy_i         (o_buf_wb_busy_q),
        .w_ready_tiles_i         (w_ready_tiles_q),
        .ring_rd_off_i           (ring_rd_off_q),
        .pin_active_hkv_i        (pin_active_hkv_q),
        .k_pinned_cnt_i          (k_pinned_cnt_q),
        .v_pinned_cnt_i          (v_pinned_cnt_q),
        .drain_start_pulse_o     (drain_start_pulse),
        .sm_drain_req_o          (sm_drain_req),
        .sm_drain_idx_o          (sm_drain_idx),
        .sm_row_start_o          (sm_row_start),
        .auto_causal_mask_o      (auto_causal_mask),
        .cmp_state_o             (cmp_state_q),
        .pinit_sync_o            (pinit_sync),
        .a_cmp_rd_sel_o          (a_cmp_rd_sel_q),
        .o_cmp_sel_o             (o_cmp_sel_q),
        .last_o_chunk_o          (last_o_chunk),
        .last_macro_m_o          (last_macro_m),
        .w_release_credit_pulse_o(w_release_credit_pulse),
        .macro_a_rel_pulse_o     (macro_a_rel_pulse),
        .o_flush_commit_pulse_o  (o_flush_commit_pulse),
        .kv_pin_rel_hkv_pulse_o  (kv_pin_rel_hkv_pulse),
        .attn_k_ready_o          (attn_k_ready),
        .attn_v_ready_o          (attn_v_ready),
        .o_wb_bytes_o            (o_wb_bytes_q),
        .attn_wb_bytes_o         (attn_wb_bytes_q),
        .o_wb_macro_step_o       (o_wb_macro_step),
        .a_step_h_o              (a_step_h_q),
        .a_full_bytes_o          (a_full_bytes_q),
        .kt_stride_o             (kt_stride_q),
        .kt_stride_attn_o        (kt_stride_attn_q),
        .sz_kv0_o                (sz_kv0_q),
        .k_blk_head_blk_o        (k_blk_head_blk),
        .k_preload_step_blk_o    (k_preload_step_blk),
        .packed_k_step_blk_o     (packed_k_step_blk),
        .packed_v_off_idx_o      (packed_v_off_idx_q),
        .cnt_gn_o                (cnt_gn_q),
        .cnt_gm_o                (cnt_gm_q),
        .cnt_gk_o                (cnt_gk_q),
        .cnt_kt_o                (cnt_kt_q),
        .cnt_gbeat_o             (cnt_gbeat_q),
        .cnt_h_o                 (cnt_h_q),
        .cnt_qi_o                (cnt_qi_q),
        .cnt_dvi_o               (cnt_dvi_q),
        .cnt_kj_o                (cnt_kj_q),
        .cnt_m_o                 (cnt_m_q),
        .cnt_dr_o                (cnt_dr_q),
        .qk_compute_fire_o       (qk_compute_fire),
        .pv_compute_fire_o       (pv_compute_fire),
        .act_start_o             (act_start_o),
        .act_base_o              (act_base_o),
        .act_k_blocks_o          (act_k_blocks_o),
        .act_k_stride_o          (act_k_stride_o),
        .act_tokens_o            (act_tokens_o),
        .act_token_stride_o      (act_token_stride_o),
        .act_busy_i              (act_busy_i),
        .act_valid_i             (act_valid_i),
        .act_ready_o             (act_ready_o),
        .wt_start_o              (wt_start_o),
        .wt_base_o               (wt_base_o),
        .wt_repeat_o             (wt_repeat_o),
        .wt_k_blocks_o           (wt_k_blocks_o),
        .wt_k_stride_o           (wt_k_stride_o),
        .wt_num_tiles_o          (wt_num_tiles_o),
        .wt_tile_step_o          (wt_tile_step_o),
        .wt_busy_i               (wt_busy_i),
        .wt_valid_i              (wt_valid_i),
        .wt_ready_o              (wt_ready_o),
        .wo_start_o              (wo_start_o),
        .wo_mode_o               (wo_mode_o),
        .wo_base_o               (wo_base_o),
        .wo_num_vectors_o        (wo_num_vectors_o),
        .wo_line_stride_o        (wo_line_stride_o),
        .wo_num_batches_o        (wo_num_batches_o),
        .wo_batch_stride_o       (wo_batch_stride_o),
        .wo_dim2_cnt_o           (wo_dim2_cnt_o),
        .wo_dim2_stride_o        (wo_dim2_stride_o),
        .wo_dim3_cnt_o           (wo_dim3_cnt_o),
        .wo_dim3_stride_o        (wo_dim3_stride_o),
        .wo_busy_i               (wo_busy_i),
        .wo_done_i               (wo_done_i),
        .v_start_o               (v_start_o),
        .v_num_batches_o         (v_num_batches_o),
        .v_busy_i                (v_busy_i),
        .v_done_i                (v_done_i),
        .rd_start_o              (rd_start_o),
        .rd_base_o               (rd_base_o),
        .rd_num_vectors_o        (rd_num_vectors_o),
        .rd_line_stride_o        (rd_line_stride_o),
        .rd_vec_stride_o         (rd_vec_stride_o),
        .rd_num_batches_o        (rd_num_batches_o),
        .rd_batch_stride_o       (rd_batch_stride_o),
        .rd_busy_i               (rd_busy_i),
        .rd_done_i               (rd_done_i),
        .cfg_mode_o              (cfg_mode_o),
        .cfg_enable_slq_o        (cfg_enable_slq_o),
        .lane_valid_o            (lane_valid_o),
        .lane_acc_idx_o          (lane_acc_idx_o),
        .p_fifo_empty_i          (p_fifo_empty_i),
        .p_fifo_almost_full_i    (p_fifo_almost_full_i)
    );

    // =========================================================================
    // SUB-FSM 2: SHARED PORT-B DRAIN & OUT_PIPE_CREDITS GUARD
    // =========================================================================
    snax_seq_dr_fsm #(
        .NUM_LANES        (NUM_LANES),
        .OUT_PIPE_CREDITS (OUT_PIPE_CREDITS)
    ) u_dr_fsm (
        .clk                   (clk),
        .rst_n                 (rst_n),
        .start_i               (start_i),
        .is_gemm_i             (is_gemm),
        .is_attn_i             (is_attn),
        .cfg_gemm_decode_i     (cfg_gemm_decode_i),
        .cfg_attn_m_q_i        (cfg_attn_m_q_i),
        .core_fp16_valid_i     (core_fp16_valid_i),
        .core_fp16_ready_i     (core_fp16_ready_i),
        .core_out_fifo_ready_i (core_out_fifo_ready_i),
        .drain_start_pulse_i   (drain_start_pulse),
        .cnt_gbeat_i           (cnt_gbeat_q),
        .sm_drain_req_i        (sm_drain_req),
        .sm_drain_idx_i        (sm_drain_idx),
        .sm_row_start_i        (sm_row_start),
        .auto_causal_mask_i    (auto_causal_mask),
        .dr_busy_o             (dr_busy),
        .gemm_beat_ok_o        (gemm_beat_ok),
        .inflight_out_cnt_o    (inflight_out_cnt_q),
        .dr_state_o            (dr_state_q),
        .dr_slot_o             (dr_slot_q),
        .tile_drain_req_o      (tile_drain_req_o),
        .tile_drain_idx_o      (tile_drain_idx_o),
        .tile_clear_on_drain_o (tile_clear_on_drain_o),
        .cfg_row_start_o       (cfg_row_start_o),
        .cfg_key_mask_o        (cfg_key_mask_o)
    );

    // =========================================================================
    // SUB-FSM 3: DMA ARBITER, RING, PING-PONG & KV-PIN CONTROLLER
    // =========================================================================
    snax_seq_dma_fsm #(
        .ADDR_WIDTH      (ADDR_WIDTH),
        .NUM_RING_SLOTS  (NUM_RING_SLOTS),
        .SLOT_SIZE_BYTES (SLOT_SIZE_BYTES)
    ) u_dma_fsm (
        .clk                     (clk),
        .rst_n                   (rst_n),
        .start_i                 (start_i),
        .is_dma_wb_i             (is_dma_wb),
        .is_gemm_i               (is_gemm),
        .is_attn_i               (is_attn),
        .is_vtrans_i             (is_vtrans),
        .is_rdback_i             (is_rdback),
        .cfg_enable_dma_i        (cfg_enable_dma_i),
        .macro_dma_en_i          (macro_dma_en),
        .attn_kv_pin_en_i        (attn_kv_pin_en),
        .w_ring_reuse_active_i   (w_ring_reuse_active),
        .cfg_gemm_decode_i       (cfg_gemm_decode_i),
        .cfg_out_mode_i          (cfg_out_mode_i),
        .cfg_gemm_k_tiles_m1_i   (cfg_gemm_k_tiles_m1_i),
        .cfg_act_bank_layout_i   (cfg_act_bank_layout_i),
        .cfg_out_bank_layout_i   (cfg_out_bank_layout_i),
        .cfg_gemm_n_tiles_i      (cfg_gemm_n_tiles_i),
        .cfg_gemm_m_tiles_i      (cfg_gemm_m_tiles_i),
        .cfg_gqa_group_m1_i      (cfg_gqa_group_m1_i),
        .cfg_attn_h_i            (cfg_attn_h_i),
        .cfg_attn_q_tiles_i      (cfg_attn_q_tiles_i),
        .cfg_attn_dv_tiles_i     (cfg_attn_dv_tiles_i),
        .cfg_attn_kv_tiles_i     (cfg_attn_kv_tiles_i),
        .cfg_attn_k_blocks_i     (cfg_attn_k_blocks_i),
        .cfg_attn_sep_kv_i       (cfg_attn_sep_kv_i),
        .cfg_tcdm_ring_base_i    (cfg_tcdm_ring_base_i),
        .cfg_tcdm_q_base_i       (cfg_tcdm_q_base_i),
        .cfg_tcdm_out_base_i     (cfg_tcdm_out_base_i),
        .cfg_dram_kv_base_i      (cfg_dram_kv_base_i),
        .cfg_stride_tile_i       (cfg_stride_tile_i),
        .cfg_dram_act_base_i     (cfg_dram_act_base_i),
        .cfg_dram_out_base_i     (cfg_dram_out_base_i),
        .cfg_dram_v_base_i       (cfg_dram_v_base_i),
        .macro_m_total_i         (macro_m_total),
        .eff_m_sub_i             (eff_m_sub),
        .a_stride_eff_i          (a_stride_eff),
        .o_stride_eff_i          (o_stride_eff),
        .o_cmp_base_0_i          (o_cmp_base_0),
        .o_dma_is_16bank_i       (o_dma_is_16bank),
        .cmp_state_i             (cmp_state_q),
        .pinit_sync_i            (pinit_sync),
        .a_cmp_rd_sel_i          (a_cmp_rd_sel_q),
        .o_cmp_sel_i             (o_cmp_sel_q),
        .last_o_chunk_i          (last_o_chunk),
        .last_macro_m_i          (last_macro_m),
        .w_release_credit_pulse_i(w_release_credit_pulse),
        .macro_a_rel_pulse_i     (macro_a_rel_pulse),
        .o_flush_commit_pulse_i  (o_flush_commit_pulse),
        .kv_pin_rel_hkv_pulse_i  (kv_pin_rel_hkv_pulse),
        .attn_k_ready_i          (attn_k_ready),
        .attn_v_ready_i          (attn_v_ready),
        .o_wb_bytes_i            (o_wb_bytes_q),
        .attn_wb_bytes_i         (attn_wb_bytes_q),
        .o_wb_macro_step_i       (o_wb_macro_step),
        .a_step_h_i              (a_step_h_q),
        .a_full_bytes_i          (a_full_bytes_q),
        .kt_stride_i             (kt_stride_q),
        .kt_stride_attn_i        (kt_stride_attn_q),
        .sz_kv0_i                (sz_kv0_q),
        .k_blk_head_blk_i        (k_blk_head_blk),
        .k_preload_step_blk_i    (k_preload_step_blk),
        .packed_k_step_blk_i     (packed_k_step_blk),
        .packed_v_off_idx_i      (packed_v_off_idx_q),
        .dma_state_o             (dma_state_q),
        .dma_busy_o              (dma_busy_q),
        .w_buf_ready_o           (w_buf_ready),
        .a_buf_ready_o           (a_buf_ready),
        .o_buf_wb_busy_o         (o_buf_wb_busy_q),
        .w_ready_tiles_o         (w_ready_tiles_q),
        .ring_rd_off_o           (ring_rd_off_q),
        .pin_active_hkv_o        (pin_active_hkv_q),
        .k_pinned_cnt_o          (k_pinned_cnt_q),
        .v_pinned_cnt_o          (v_pinned_cnt_q),
        .dma_req_valid_o         (dma_req_valid_o),
        .dma_req_ready_i         (dma_req_ready_i),
        .dma_req_dir_o           (dma_req_dir_o),
        .dma_req_dram_addr_o     (dma_req_dram_addr_o),
        .dma_req_tcdm_addr_o     (dma_req_tcdm_addr_o),
        .dma_req_size_bytes_o    (dma_req_size_bytes_o),
        .dma_done_i              (dma_done_i)
    );

    // =========================================================================
    // SECTION 4: TOP-LEVEL STATUS
    // =========================================================================
    wire cmp_active    = (cmp_state_q != CMP_IDLE) && (cmp_state_q != CMP_DONE);
    wire macro_wb_busy = macro_dma_en && ((o_buf_wb_busy_q != 2'b00) || dma_busy_q);

    assign busy_o = cmp_active || dr_busy || (inflight_out_cnt_q != 4'd0) ||
                    v_busy_i || rd_busy_i || wo_busy_i || macro_wb_busy;
    assign done_o = (cmp_state_q == CMP_DONE) && !dr_busy && (inflight_out_cnt_q == 4'd0) &&
                    !v_busy_i && !rd_busy_i && !wo_busy_i && !macro_wb_busy;

endmodule
